const taleNamingMarker = '_';

module.exports = taleIdentifier => {
  const parts = taleIdentifier.split (taleNamingMarker);
  return {
    componentName: parts[0],
    siblings: parts.map ((_, index) => {
      let name = '';
      for (let i = 0; i <= index; i++)
        name += (i === 0 ? '' : taleNamingMarker) + parts[i];
      return name;
    }),
  };
};
